int n_hit = 0;
double x, y;

// Linear Congruential Generator parameters
const unsigned long long lcg_a = 1664525;
const unsigned long long lcg_c = 1013904223;
const unsigned long long lcg_m = 4294967296; // 2^32

for (int i = 0; i < n_points; ++i) {
    // Generate random x in [a, b]
    seed = (lcg_a * seed + lcg_c) % lcg_m;
    x = a + (static_cast<double>(seed) / lcg_m) * (b - a);

    // Generate random y in [0, fmax]
    seed = (lcg_a * seed + lcg_c) % lcg_m;
    y = (static_cast<double>(seed) / lcg_m) * fmax;

    if (f(x) > y) {
        n_hit++;
    }
}

return std::abs(b - a) * fmax * (static_cast<double>(n_hit) / static_cast<double>(n_points));

